import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2010年 · 铁路新时代","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2010年.md","filePath":"05_quotes/by-year/2010年.md"}'),r={name:"05_quotes/by-year/2010年.md"};function s(u,e,c,q,_,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2010年-·-铁路新时代" tabindex="-1">2010年 · 铁路新时代 <a class="header-anchor" href="#_2010年-·-铁路新时代" aria-label="Permalink to &quot;2010年 · 铁路新时代&quot;">​</a></h1><blockquote><p>资金总是流向机会所在，而美国充满了机会。——巴菲特（80岁）</p></blockquote><p>本页收录2010年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>不要让这一现实吓倒你。在我的一生中，政客和评论员一直在哀叹美国面临的可怕问题。然而，我们的公民现在的生活水平比我出生时高出惊人的六倍。</p></blockquote><blockquote><p>今天的评论员经常谈论&quot;巨大的不确定性&quot;。但无论如何，明天总是不确定的。</p></blockquote><blockquote><p>我们天生并不比我们建国时更聪明，也不比我们更努力工作。但环顾四周，你会看到一个超越任何殖民者梦想的世界。</p></blockquote><blockquote><p>现在，正如1776年、1861年、1932年和1941年一样，美国最好的日子还在前方。</p></blockquote><blockquote><p>资金总是流向机会所在，而美国充满了机会。</p></blockquote><blockquote><p>时间是伟大企业的朋友。</p></blockquote><blockquote><p>投资是现在投入资金以期望在未来获得更多资金的过程。更简洁地说，投资是现在放弃消费，以便在以后有能力消费更多。</p></blockquote><blockquote><p>风险不是用beta衡量——那是太多学者的选择。真正的风险是用该投资导致其所有者在预期持有期内购买力损失的概率来衡量。</p></blockquote><blockquote><p>我们既需要现有业务的良好表现，也需要更多重大收购。我们的大象枪已经重新装填，我的扳机手指已经发痒。</p></blockquote><blockquote><p>良好的投资者为收购业务带来有用的视角，我们期望他们被咨询——但没有投票权——关于可能收购的智慧。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2010年，巴菲特完成收购BNSF铁路公司，使伯克希尔的&quot;正常&quot;盈利能力税前增长近40%。这是巴菲特职业生涯最大手笔的收购之一，标志着伯克希尔进入铁路运输这一资本密集型公用事业领域。巴菲特在信中表达了对美国经济长期看多的坚定信念，强调最好的日子还在前方。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2010年-翻译-·-01-letters-2010年-核心总结-·-01-letters-2010年-思维导图" tabindex="-1"><a href="/01_letters/2010年/翻译">01_letters/2010年/翻译</a> · <a href="/01_letters/2010年/核心总结">01_letters/2010年/核心总结</a> · <a href="/01_letters/2010年/思维导图">01_letters/2010年/思维导图</a> <a class="header-anchor" href="#_01-letters-2010年-翻译-·-01-letters-2010年-核心总结-·-01-letters-2010年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2010年/翻译]] · [[→ 核心总结|01_letters/2010年/核心总结]] · [[→ 思维导图|01_letters/2010年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2010年/翻译">/01_letters/2010年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{i as __pageData,p as default};
